const AUTH_KEY = 'greenpaper_auth_v3';
const USERS_KEY = 'greenpaper_users_v3';

const APP = {
  state: {
    route: location.hash.replace('#','') || 'dashboard',
    search: '',
    filters: {},
    modal: null,
    user: loadAuth(),
    sapSync: { status: 'CONNECTING', lastSync: null, nextSync: null, employeeCounts: {}, error: null, inFlight: false },
  },
  icons: {
    dashboard:'⌂', customers:'◉', enquiries:'◌', quotations:'▤', orders:'▣', approvals:'✓',
    inventory:'◫', production:'⚙', quality:'◍', dispatch:'⇧', delivery:'⌁', invoices:'▧',
    payments:'₹', reports:'▥', profile:'◯', settings:'⚙'
  }
};

const ROLES = ['Sales Manager','Production','Management'];

function deepClone(value){ return JSON.parse(JSON.stringify(value)); }
function loadAuth(){ try { return JSON.parse(localStorage.getItem(AUTH_KEY)) || null; } catch { return null; } }
function getUsers(){ try { return JSON.parse(localStorage.getItem(USERS_KEY)) || []; } catch { return []; } }
function setUsers(users){ localStorage.setItem(USERS_KEY, JSON.stringify(users)); }
function saveAuth(user){ APP.state.user=user; if(user) localStorage.setItem(AUTH_KEY,JSON.stringify(user)); else localStorage.removeItem(AUTH_KEY); }
function escapeHtml(value){ return String(value ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])); }
function money(n){ return '₹'+Number(n||0).toLocaleString('en-IN'); }
function fmtDate(d){ if(!d) return '—'; const x=new Date(d); return Number.isNaN(x.getTime()) ? d : x.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}); }
function nowDate(){ return new Date().toISOString().slice(0,10); }
function nowTime(){ return new Date().toTimeString().slice(0,8); }
function setSapSyncState(patch){ APP.state.sapSync={...APP.state.sapSync,...patch}; }
function sapStatusLabel(){const s=APP.state.sapSync.status;return s==='CONNECTED'?'Connected':s==='SYNCING'?'Synchronizing…':s==='ERROR'?'Connection error':'Connecting…';}
function sapStatusClass(){const s=APP.state.sapSync.status;return s==='CONNECTED'?'green':s==='ERROR'?'red':'amber';}
function sapDateTime(v){return v?new Date(v).toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'Not synchronized yet';}
function ensureSapCustomer(row){const k=String(row.KUNNR||'').trim();const name=String(row.NAME1||'').trim()||`SAP Customer ${k||'Unknown'}`;if(!k)return {id:'SAPC-UNKNOWN',name,code:'—'};let c=APP.db.customers.find(x=>x.sapKunnr===k||x.id===`SAPC-${k}`);if(!c){c={id:`SAPC-${k}`,sapKunnr:k,code:k,name,gst:'—',city:'—',terms:'—',owner:row.ZNAME11||'SAP',outstanding:0,status:'Active'};APP.db.customers.push(c);}else{c.name=name;c.owner=row.ZNAME11||c.owner;}return c;}
function ensureSapProduct(row){const m=String(row.MATNR||'').trim();if(!m)return {id:'SAP-PRODUCT-UNKNOWN',name:String(row.ARKTX||'SAP Product'),code:'—',grade:'SAP',gsm:'—',size:'—',form:'SAP',finish:'—',unit:String(row.VRKME||'')||'EA',rate:Number(row.NETPR||0)};let p=APP.db.products.find(x=>x.sapMatnr===m||x.id===`SAP-${m}`);if(!p){p={id:`SAP-${m}`,sapMatnr:m,code:m,name:String(row.ARKTX||m),grade:'SAP',gsm:'—',size:'—',form:'SAP',finish:'—',unit:String(row.VRKME||'')||'EA',rate:Number(row.NETPR||0)};APP.db.products.push(p);}else{p.name=String(row.ARKTX||p.name);p.unit=String(row.VRKME||p.unit);p.rate=Number(row.NETPR||0);}return p;}
function normalizeSapApproval(order,a){if(a){const raw=String(a.STATUS??'').trim().toUpperCase();order.approvalStatus=raw==='A'?'APPROVED':raw==='R'?'REJECTED':raw==='P'?'PENDING':raw||'UNKNOWN';order.sapApprovalStatus=raw||'—';order.approvalUser=a.USERNAME||'';order.approvalDate=a.ZDATE||'';order.approvalTime=a.ZTIME||'';order.sapApprovalCode=a.ACODE||order.sapApprovalCode||'';order.sapApprovalUser=a.ZNAME11||order.sapApprovalUser||'';}else{const z=String(order.sapZname||'').toUpperCase();order.approvalStatus=z.includes('NOT APPROVED')||z.includes('APPROVAL')?'PENDING':order.approvalStatus||'UNKNOWN';}}
function upsertSapOrders(rows,approvals,employee){const groups=new Map();(Array.isArray(rows)?rows:[]).forEach((r,i)=>{const v=String(r.VBELN||'').trim();if(v){if(!groups.has(v))groups.set(v,[]);groups.get(v).push({...r,__rowIndex:i});}});const amap=new Map();(Array.isArray(approvals)?approvals:[]).forEach(a=>{const v=String(a.VBELN||'').trim();if(v)amap.set(v,a);});let count=0;groups.forEach((lines,vbeln)=>{const first=lines[0],c=ensureSapCustomer(first);let o=APP.db.orders.find(x=>x.sapNo===vbeln);const items=lines.map(r=>{const pr=ensureSapProduct(r);return {productId:pr.id,sapPosnr:r.POSNR??'',matnr:r.MATNR||'',description:r.ARKTX||pr.name,qty:Number(r.KWMENG||0),unit:r.VRKME||pr.unit,rate:Number(r.NETPR||0),netValue:Number(r.NETWR||0),discount:0,tax:0,raw:r};});const total=items.reduce((a,x)=>a+x.netValue,0);if(!o){o={id:`SO-SAP-${vbeln}`,sapNo:vbeln,source:'SAP',customerId:c.id,customerPO:first.BSTKD||'—',orderDate:first.AUDAT||first.ERDAT||'',deliveryDate:'',plant:first.WERKS||'—',subtotal:total,discount:0,tax:0,freight:0,total,orderStatus:'SAP',approvalStatus:'UNKNOWN',currentStage:null,syncStatus:'SYNCED',createdBy:first.ERNAM||first.ZNAME11||'SAP',items:[]};APP.db.orders.push(o);}Object.assign(o,{sapEmployee:employee,sapClient:first.MANDT||'100',customerId:c.id,customerPO:first.BSTKD||o.customerPO||'—',orderDate:first.AUDAT||first.ERDAT||o.orderDate,plant:first.WERKS||o.plant,subtotal:total,total,syncStatus:'SYNCED',createdBy:first.ERNAM||first.ZNAME11||o.createdBy,sapZname:first.ZNAME||'',sapStat:first.STAT||'',sapApprovalCode:first.ACODE||'',sapApprovalUser:first.ZNAME11||'',sapRows:lines.length});o.items=items;normalizeSapApproval(o,amap.get(vbeln));o.orderStatus=o.approvalStatus==='APPROVED'?'Approved':o.approvalStatus==='REJECTED'?'Rejected':o.approvalStatus==='PENDING'?'Pending Approval':'SAP';count++;});return count;}
async function fetchSapJson(url){const r=await fetch(url,{cache:'no-store'});const text=await r.text();let d;try{d=JSON.parse(text);}catch{throw new Error(`SAP returned non-JSON (${r.status})`);}if(!r.ok)throw new Error(d.error||`SAP request failed (${r.status})`);return d;}
async function syncSAP(silent=false){if(APP.state.sapSync.inFlight)return;setSapSyncState({status:'SYNCING',inFlight:true,error:null});if(!silent)toast('Synchronizing live SAP data…');render();try{const [a,b,soa]=await Promise.all([fetchSapJson('/api/sap/orders?employee=E0003'),fetchSapJson('/api/sap/orders?employee=E0006'),fetchSapJson('/api/sap/approvals')]);const approvals=Array.isArray(soa)?soa:(soa.data||[]);const c3=upsertSapOrders(Array.isArray(a)?a:(a.data||[]),approvals,'E0003');const c6=upsertSapOrders(Array.isArray(b)?b:(b.data||[]),approvals,'E0006');const last=new Date().toISOString(),next=new Date(Date.now()+15*60*1000).toISOString();setSapSyncState({status:'CONNECTED',lastSync:last,nextSync:next,employeeCounts:{E0003:c3,E0006:c6},inFlight:false,error:null});APP.db.sapConnection={status:'CONNECTED',lastSync:last,nextSync:next};APP.db.sapLastSync=last;saveDB();if(!silent)toast(`SAP sync completed • E0003: ${c3} • E0006: ${c6}`);render();}catch(err){setSapSyncState({status:'ERROR',inFlight:false,error:err.message});APP.db.sapConnection={status:'ERROR',lastSync:APP.state.sapSync.lastSync,error:err.message};saveDB();if(!silent)toast(`SAP sync failed: ${err.message}`,'error');render();}}
function startSapAutoSync(){syncSAP(true);setInterval(()=>syncSAP(true),15*60*1000);}
function customer(id){ return APP.db.customers.find(x=>x.id===id) || {name:'Unknown Customer',code:'—',gst:'—',city:'—',terms:'—',owner:'—',outstanding:0,status:'Active'}; }
function product(id){ return APP.db.products.find(x=>x.id===id) || {name:'Unknown Product',code:'—',grade:'—',gsm:'—',size:'—',form:'—',finish:'—',unit:'MT',rate:0}; }
function statusBadge(status){
  const s=String(status||'').toUpperCase(); let c='gray';
  if(['APPROVED','PASSED','PAID','DELIVERED','COMPLETED','AVAILABLE','SYNCED','DISPATCHED','ACTIVE'].includes(s)) c='green';
  else if(['IN PRODUCTION','IN TRANSIT','PARTIALLY DELIVERED','RAW MATERIAL ALLOCATED','QUALITY INSPECTION','READY','SCHEDULED'].includes(s)) c='blue';
  else if(['PENDING','DRAFT','SUBMITTED','PARTIALLY AVAILABLE','PARTIALLY PAID','STAGE_1_PENDING','STAGE_2_PENDING','STAGE_3_PENDING','PLANNED','NEW','SENT'].includes(s)) c='amber';
  else if(['REJECTED','FAILED','OVERDUE','DELAYED','CANCELLED','SYNC FAILED','SENT BACK','ON HOLD','SHORTAGE'].includes(s)) c='red';
  return `<span class="badge ${c}">${escapeHtml(status||'—')}</span>`;
}
function toast(message,type='success'){
  const root=document.getElementById('toast-root'); if(!root) return;
  root.innerHTML=`<div class="toast-msg ${type}">${escapeHtml(message)}</div>`;
  setTimeout(()=>{ root.innerHTML=''; },2800);
}
function audit(orderId,action,user){
  APP.db.audit.unshift({id:'LOG-'+Date.now(),orderId,action,user,time:`${nowDate()} ${nowTime()}`});
}

